PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS store (id TEXT PRIMARY KEY, name TEXT NOT NULL, slogan TEXT, logo_path TEXT, phone TEXT, address TEXT, card_number TEXT, card_holder TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS category (id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES store(id), name TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, archived_at TEXT);
CREATE TABLE IF NOT EXISTS product (id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES store(id), category_id TEXT REFERENCES category(id), sku TEXT, name TEXT NOT NULL, search_name TEXT NOT NULL, description TEXT, image_path TEXT, image_sha256 TEXT, price_rial INTEGER NOT NULL CHECK(price_rial>=0), unit TEXT NOT NULL DEFAULT 'عدد', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT, revision INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS product_sku_unique ON product(store_id, sku) WHERE sku IS NOT NULL;
CREATE INDEX IF NOT EXISTS product_search ON product(store_id, search_name, archived_at);
CREATE TABLE IF NOT EXISTS customer (id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES store(id), name TEXT NOT NULL, phone TEXT, address TEXT, created_at TEXT NOT NULL, archived_at TEXT);
CREATE TABLE IF NOT EXISTS price_batch (id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES store(id), percent_basis_points INTEGER NOT NULL, scope TEXT NOT NULL CHECK(scope IN ('all','selected','undo')), source_batch_id TEXT REFERENCES price_batch(id), created_at TEXT NOT NULL, actor TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS price_event (id TEXT PRIMARY KEY, batch_id TEXT REFERENCES price_batch(id), product_id TEXT NOT NULL REFERENCES product(id), old_price_rial INTEGER NOT NULL, new_price_rial INTEGER NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS price_event_history ON price_event(product_id, created_at);
CREATE TABLE IF NOT EXISTS stock_balance (product_id TEXT PRIMARY KEY REFERENCES product(id), quantity_milli INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS stock_movement (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES product(id), quantity_milli INTEGER NOT NULL, reason TEXT NOT NULL, invoice_revision_id TEXT REFERENCES invoice_revision(id), created_at TEXT NOT NULL, CHECK(quantity_milli<>0));
CREATE INDEX IF NOT EXISTS stock_history ON stock_movement(product_id, created_at);
CREATE TABLE IF NOT EXISTS template_version (id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES store(id), version_no INTEGER NOT NULL, palette TEXT NOT NULL CHECK(palette IN ('color','mono')), created_at TEXT NOT NULL, UNIQUE(store_id,version_no,palette));
CREATE TABLE IF NOT EXISTS template_field (template_version_id TEXT NOT NULL REFERENCES template_version(id), field_key TEXT NOT NULL, section_key TEXT NOT NULL, label TEXT NOT NULL, value_text TEXT, visible INTEGER NOT NULL CHECK(visible IN (0,1)), sort_order INTEGER NOT NULL, bounds_json TEXT NOT NULL, PRIMARY KEY(template_version_id,field_key));
CREATE TABLE IF NOT EXISTS invoice (id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES store(id), customer_id TEXT REFERENCES customer(id), invoice_number INTEGER, status TEXT NOT NULL CHECK(status IN ('draft','issued','void')), current_revision INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, issued_at TEXT, UNIQUE(store_id,invoice_number));
CREATE TABLE IF NOT EXISTS invoice_counter (store_id TEXT PRIMARY KEY REFERENCES store(id), next_number INTEGER NOT NULL CHECK(next_number>0));
CREATE TABLE IF NOT EXISTS invoice_revision (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoice(id), revision_no INTEGER NOT NULL, template_version_id TEXT REFERENCES template_version(id), snapshot_json TEXT NOT NULL, subtotal_rial INTEGER NOT NULL, discount_rial INTEGER NOT NULL, shipping_rial INTEGER NOT NULL, grand_total_rial INTEGER NOT NULL, paid_rial INTEGER NOT NULL, balance_rial INTEGER NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(invoice_id,revision_no), CHECK(grand_total_rial=subtotal_rial-discount_rial+shipping_rial), CHECK(balance_rial=grand_total_rial-paid_rial));
CREATE TABLE IF NOT EXISTS invoice_line (id TEXT PRIMARY KEY, invoice_revision_id TEXT NOT NULL REFERENCES invoice_revision(id), product_id TEXT REFERENCES product(id), name_snapshot TEXT NOT NULL, code_snapshot TEXT, color_snapshot TEXT, unit_snapshot TEXT NOT NULL, quantity_milli INTEGER NOT NULL CHECK(quantity_milli>0), unit_price_rial INTEGER NOT NULL CHECK(unit_price_rial>=0), discount_rial INTEGER NOT NULL DEFAULT 0 CHECK(discount_rial>=0), line_total_rial INTEGER NOT NULL CHECK(line_total_rial>=0));
CREATE TABLE IF NOT EXISTS payment (id TEXT PRIMARY KEY, invoice_revision_id TEXT NOT NULL REFERENCES invoice_revision(id), amount_rial INTEGER NOT NULL CHECK(amount_rial>0), method TEXT NOT NULL, paid_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_event (id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES store(id), entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, payload_json TEXT NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_timeline ON audit_event(store_id, created_at);
INSERT OR IGNORE INTO schema_migrations(version,applied_at) VALUES(1,datetime('now'));
